import Config

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :app, AppWeb.Endpoint, cache_static_manifest: "priv/static/cache_manifest.json"

# Force using SSL in production. This also sets the "strict-security-transport" header,
# known as HSTS. If you have a health check endpoint, you may want to exclude it below.
# Note `:force_ssl` is required to be set at compile-time.
#
# Relies on `X-Forwarded-Proto` from the reverse proxy in front (Caddy in
# infra/, which sets it automatically) — a raw TCP tunnel without an
# HTTP-aware proxy in front (e.g. a bare SSH port-forward used for local
# Apps Script shim testing) can't provide that header and
# will redirect-loop under this config; that's a local-testing-only
# concern, never disable this for a real deploy.
config :app, AppWeb.Endpoint,
  force_ssl: [
    rewrite_on: [:x_forwarded_proto],
    exclude: [
      # paths: ["/health"],
      hosts: ["localhost", "127.0.0.1"]
    ]
  ]

# same_site: "None" is required for the embedded /sheets
# LiveView's session cookie to survive Google's third-party sandboxed
# iframe (Chrome drops SameSite=Lax there entirely). Safe here specifically
# because the session cookie is always Secure alongside it (browsers drop
# SameSite=None without Secure). See lib/app_web/endpoint.ex.
config :app, session_same_site: "None"

# Configure Swoosh API Client
config :swoosh, api_client: Swoosh.ApiClient.Req

# Disable Swoosh Local Memory Storage
config :swoosh, local: false

# Do not print debug messages in production
config :logger, level: :info

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.
